from pathlib import Path
import json,csv,collections
BASE=Path(__file__).resolve().parents[1]
talks=[];items=[];problems=[];corrections=[]
def talk(record,date,speaker,pages,title,summary,kind='talk'):
 talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def item(record,pages,kind,title,notes,statement,fate,refs=None,reconstruction='',cls='E',literal='correct with missing hypotheses',match='exact',verification='read the result',development='none',problem='',worth='',confidence='high',speaker=None,status=None):
 n=1+sum(x['record']==record for x in items)
 d=dict(id=f'1974-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=status or 'As of November 2026: established in the stated scope; the notebook is an expository occurrence, not a new open problem.',literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=refs or [],confidence=confidence)
 if speaker:d['speaker']=speaker
 items.append(d)
 return d['id']
def corr(page,place,reads,should,evidence,applies='both',type='faithful_error'):
 corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=type))
def save():
 for name,v in [('talks',talks),('items',items),('problems',problems)]:
  (BASE/f'late_{name}.json').write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
 with (BASE/'late_corrections.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)
 print('saved',len(talks),'records',len(items),'items',len(problems),'problems',len(corrections),'corrections')

H='hormander1971fourier';DH='duistermaathormander1972fourierii';D='dobrushin1968conditional';DU='dobrushin1968uniqueness';R='ruelle1970superstable';PS='pirogovsinai1975phase';PS2='pirogovsinai1976phase';GK='griffithsking1973nevanlinna';G='griffiths1971canonical';HE='heifetz1985padic'
talk(352,'','—','P000583-P000585','Year 1975: catalogue heading',r"""This MCCME record is a year heading, not a separate mathematical talk. Its catalogue range overlaps the end of Graev\textquotesingle s record 351 and the beginning of the dated 17 February session. No mathematical occurrence is assigned merely to the heading.""",kind='heading')
talk(353,'1975-02-17','V. N. Tulovskii','P000583-P000586','Wavefront sets, products, and Schwartz kernels',r"""The dated heading begins on P000584 and explicitly says \ru{ИОФ --- I и II}. The notes review microlocal regularity, multiplication of distributions, and propagation through kernels; the composition formula continues onto P000585, before Sinai\textquotesingle s heading. This revisits 1971-234 and especially 1973-329. Gelfand intervenes with slicing and a proposed extension from linear to polynomial integration. The mathematical backbone is already in \citet[\S2.5]{hormander1971fourier}.""")
item(353,'P000584','definition','The smooth wavefront set',r"""\((x_0,\xi_0)\notin\mathrm{WF}(u)\) when a cutoff \(\varphi(x_0)\ne0\) makes \(\widetilde{u\varphi}\) rapidly decreasing in an angular neighbourhood of \(\xi_0\).""",r"""For an open \(\Omega\subset\mathbb R^n\) and \(u\in\mathcal D'(\Omega)\), a nonzero covector \((x_0,\xi_0)\) is outside \(\mathrm{WF}(u)\) iff some \(\varphi\in C_c^\infty(\Omega)\), equal to one near \(x_0\), and an open cone \(V\ni\xi_0\) satisfy \(\sup_{\xi\in V}(1+|\xi|)^N|\widehat{\varphi u}(\xi)|<\infty\) for every integer \(N\ge0\).""",r"""Published in \citet[Definition 2.5.2 and pp.~121--122]{hormander1971fourier} in 1971; the equivalent Fourier description is explicit on p.~122. Earlier seminar occurrences are 1971-234.1 and 1973-329.1.""",[H],literal='correct')
item(353,'P000584','remark',"Gelfand’s hyperplane slicing interpretation",r"""Gelfand relates the smoothness of a one-variable integral over parallel hyperplanes to membership of the normal covector in the wavefront.""",r"""For a compactly supported localized distribution \(v=\chi u\), the pushforward under \(x\mapsto x\cdot\theta\) has one-dimensional Fourier transform \(\widehat v(t\theta)\). Absence from \(\mathrm{WF}(u)\) requires such rapid decay uniformly for \(\theta\) in an angular neighbourhood and with localization near \(x_0\). A single unlocalized slice integral cannot detect every covector, because cancellations are possible.""",r"""The precise directional statement follows from the Fourier characterization in \citet[p.~122]{hormander1971fourier}; this repeats the explanatory intervention 1973-329.3. It is an interpretation of an old definition, not an asserted new inversion theorem.""",[H],reconstruction=r"""The cutoff, angular uniformity, and warning about cancellation make precise the one-line analogy; they are editorial qualifications.""",speaker='I. M. Gelfand',match='partial')
item(353,'P000584','claim','One-sided analytic continuation and directional regularity',r"""For \(\xi_0>0\), the notes give \(u=\varphi+u_1\) locally, with \(\varphi\in C_c^\infty\) and \(u_1\) continuing analytically into the upper half-plane.""",r"""A holomorphic function in an upper half-disc with at most polynomial growth towards the boundary has a distributional boundary value. With Fourier convention \(\widehat u(\xi)=\int e^{+ix\xi}u(x)\,dx\), its smooth wavefront has no positive covectors in that interval; addition of a smooth function does not change this. Reversing the Fourier sign reverses the excluded half-ray. Merely saying that an arbitrary distribution continues analytically does not specify a boundary value or growth condition.""",r"""This is the standard boundary-value interpretation behind microlocal analyticity; \citet[\S2.5]{hormander1971fourier} supplies the smooth wavefront framework. The notebook fixes neither Fourier sign nor boundary-growth class, so this is a partial identification rather than an exact quotation of a theorem there.""",[H],reconstruction=r"""We state a sufficient boundary-value version and choose a Fourier convention explicitly; no unqualified equivalence is attributed to the notes.""",match='partial',verification='indirect',confidence='medium')
item(353,'P000584','theorem','Projection onto singular support',r"""\(\pi(\mathrm{WF}(u))=\operatorname{sing\,supp}u\), with \(\pi:T^*\Omega\to\Omega\).""",r"""For every distribution on a smooth manifold, the base projection of its smooth wavefront set is exactly its singular support.""",r"""\citet[Theorem 2.5.3]{hormander1971fourier}, published 1971, is an exact match. The earlier occurrence is 1973-329.4.""",[H],literal='correct')
item(353,'P000584','theorem','Frequency projection and rapid Fourier decay',r"""\(\pi'\mathrm{WF}(u)\) is called the smallest closed cone outside which the Fourier transform decreases rapidly.""",r"""For \(u\in\mathcal E'(\mathbb R^n)\), let \(K=\{\xi\ne0:\exists x,\ (x,\xi)\in\mathrm{WF}(u)\}\). Then \(K\) is closed in \(\mathbb R^n\setminus0\), and \(\widehat u\) decreases faster than every power in each closed cone disjoint from \(K\). Conversely, this property determines the smallest such closed cone. For a general local distribution apply the statement to compactly supported localizations.""",r"""Exact compact-support version: \citet[Proposition 2.5.5]{hormander1971fourier}. Compact support is missing in the notebook; without a suitable global hypothesis even an ordinary Fourier transform need not be defined.""",[H],reconstruction='Compact support is supplied from the cited theorem.')
item(353,'P000584','construction','Multiplication under the no-opposite-covectors condition',r"""For \(\mathcal D'_\Gamma=\{u:\mathrm{WF}(u)\subset\Gamma\}\), and \(\Gamma_1+\Gamma_2\) avoiding zero, the notes give a bilinear map into \(\mathcal D'_{(\Gamma_1+\Gamma_2)\cup\Gamma_1\cup\Gamma_2}\).""",r"""If \(u,v\in\mathcal D'(\Omega)\) and there is no \((x,\xi)\in\mathrm{WF}(u)\) with \((x,-\xi)\in\mathrm{WF}(v)\), their product is canonically defined by pullback of \(u\otimes v\) to the diagonal. Its wavefront is contained in \(\mathrm{WF}(u)\cup\mathrm{WF}(v)\cup\{(x,\xi+\eta):(x,\xi)\in\mathrm{WF}(u),(x,\eta)\in\mathrm{WF}(v)\}\).""",r"""\citet[Theorem 2.5.10]{hormander1971fourier} proves the closed-cone version, predating the talk. The occurrence 1973-329.11 has the same criterion. The notebook calls its containing cones open; the pointwise noncancellation criterion remains the decisive condition.""",[H],reconstruction='No continuity claim for an unspecified topology on the open-cone spaces is added.')
item(353,'P000584','construction','A distribution kernel defines an operator',r"""\(A\in\mathcal D'(\Omega_x\times\Omega_y)\) is paired with \(u(y)v(x)\), defining \(A:C_c^\infty(\Omega_y)\to\mathcal D'(\Omega_x)\).""",r"""A distribution \(K\) on \(X\times Y\), with densities understood, defines a continuous linear operator by \(\langle Au,v\rangle=\langle K,v\otimes u\rangle\). Conversely every continuous operator \(C_c^\infty(Y)\to\mathcal D'(X)\) has a unique Schwartz kernel.""",r"""This is the established Schwartz kernel formalism used in \citet[\S2.5, before Theorem 2.5.12]{hormander1971fourier}; earlier occurrence 1973-329.5.""",[H],reconstruction='Continuity and the density convention are stated explicitly.',literal='correct')
item(353,'P000584-P000585','theorem','Kernel extensions with both axis wavefronts absent',r"""If \(\mathrm{WF}(A)\) has no points with \(\xi=0\) or \(\eta=0\), then \(A:C_c^\infty(Y)\to C^\infty(X)\) and \(A:\mathcal E'(Y)\to\mathcal D'(X)\).""",r"""For \(K\in\mathcal D'(X\times Y)\), assume \(\mathrm{WF}(K)\) avoids both sets \(\{(x,\xi;y,0):\xi\ne0\}\) and \(\{(x,0;y,\eta):\eta\ne0\}\). Kernel action then maps tests to smooth functions and extends canonically and continuously to compactly supported distributions. Proper support is needed only for corresponding noncompact-input or compact-output assertions.""",r"""\citet[Theorems 2.5.12--2.5.14]{hormander1971fourier} establish these operations. This repeats 1973-329.6.""",[H],literal='correct')
item(353,'P000585','theorem','The primed relation and propagation through a kernel',r"""\(\mathrm{WF}'(A)=\{(x,\xi;y,-\eta):(x,\xi;y,\eta)\in\mathrm{WF}(A)\}\), and \(\mathrm{WF}(Au)\subset\mathrm{WF}'(A)\circ\mathrm{WF}(u)\).""",r"""Under the no-axis assumptions of the preceding item, for every \(u\in\mathcal E'(Y)\), \(\mathrm{WF}(Au)\subset\{(x,\xi):\exists(y,\eta)\in\mathrm{WF}(u),\ (x,\xi;y,\eta)\in\mathrm{WF}'(K)\}\). The minus sign belongs to the input covector of the kernel.""",r"""Exact statement in \citet[Theorem 2.5.14]{hormander1971fourier}; compare 1973-329.7--8. The preceding assumptions must remain attached to this shorthand formula.""",[H],literal='correct')
item(353,'P000585','remark','Gelfand proposes polynomial as well as linear integration',r"""\ru{Идея Г.} is followed by integrating linear functions and polynomials; a curved outline is cut by parallel segments.""",r"""The evidence supports a proposal to replace linear level sets by polynomial ones in an integral-geometric construction. It does not identify the family of polynomials, the integration measure, a target space, or an inversion or range question. Thus it determines no unique theorem or problem.""",r"""Generalized Radon transforms are thematically related to the canonical-relation calculus of \citet[\S4.1]{hormander1971fourier}, but that relation does not identify this particular proposal. The scan does not justify reading the small sketch as a specified polynomial transform.""",[H],cls='F',literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',speaker='I. M. Gelfand',status='As of November 2026: the precise intended construction is not recoverable from this entry; no claim of an undeveloped idea is made.')
item(353,'P000585','theorem','Composition of wavefront relations',r"""For \(A:\mathcal E'(Y)\to\mathcal D'(X)\), \(B:\mathcal E'(Z)\to\mathcal E'(Y)\), the notes write \(\mathrm{WF}'(A\circ B)\subset\mathrm{WF}'(A)\circ\mathrm{WF}'(B)\).""",r"""For properly supported distribution kernels whose wavefronts avoid both coordinate axes, composition is defined and its primed wavefront lies in the composite canonical relation. More generally one needs the wavefront transversality condition at the intermediate variable and must include the horizontal and vertical error sets when these are nonempty.""",r"""\citet[Theorem 2.5.15]{hormander1971fourier} gives the general inclusion, with the simpler formula after removal of the two axis terms; compare 1973-329.9.""",[H],reconstruction='The earlier no-axis hypothesis is retained and support conditions are made explicit.')
corr('P000584','Frequency-projection assertion',r"""\(u\in\mathcal D'(\Omega)\); \(\pi'\mathrm{WF}(u)\) described using its global Fourier transform.""",r"""Apply the frequency-projection statement to \(u\in\mathcal E'(\mathbb R^n)\), or to compactly supported localizations.""",r"""The scan confirms the unqualified sentence. \citet[Proposition 2.5.5]{hormander1971fourier} has compact support; this is a mathematical qualification, not a mistranscribed word.""")
save()
RO='rokhlin1949measure'
talk(354,'1975-02-17','Ya. G. Sinai','P000584-P000587','Configuration measures and finite-range Gibbs interactions',r"""Sinai's contribution starts after Tulovskii's composition formula on P000585; P000586 contains only the product-measure continuation. Gelfand participates in the configuration-space formulation. The following dated session, on P000587, belongs to record 355. This is preparatory exposition for the later phase-diagram theorem, connected to the earlier Gibbs discussions 1970-195 and 1970-200.""")
item(354,'P000585','definition','Locally finite configurations and their measurable sets',r"""Configurations are countable subsets \(X\subset\mathbb R^n\) without accumulation points; count events \(\mathrm C_{K,j}\) generate the measurable sets. The displayed set mistakenly binds \(K\), not \(X\).""",r"""Let \(\Gamma\) be the locally finite simple counting measures on \(\mathbb R^n\), identified with their point sets. Equip \(\Gamma\) with the sigma-algebra generated by \(N_B(X)=|X\cap B|\) for bounded Borel \(B\). For a fixed compact \(K\), \(\mathrm C_{K,j}=\{X\in\Gamma:N_K(X)=j\}\).""",r"""The standard measurable configuration formalism appears in \citet[Section 5]{ruelle1970superstable}; the notation in this talk is expository. Simplicity must be changed to integer-valued counting measures when the intensity has atoms.""",[R],speaker='I. M. Gelfand',literal='false as written')
item(354,'P000585','construction','The Poisson reference measure',r"""\(\rho(\mathrm C_{K,j})=m(K)^j e^{-m(K)}/j!\), for a locally compact measured space.""",r"""For a locally finite diffuse Radon measure \(m\) on a second-countable locally compact space, the Poisson process has independent counts on disjoint bounded Borel sets, and \(N_B\) is Poisson with mean \(m(B)\). On a region \(K\), its symmetric \(j\)-particle measure is \(e^{-m(K)}m^{\otimes j}/j!\), pushed to unordered configurations.""",r"""This is the usual Poisson reference in \citet[Section 5]{ruelle1970superstable}. Independence of disjoint counts completes the displayed one-set marginal formula; no new probability measure is proposed here.""",[R],reconstruction='Local finiteness, diffuseness, a standard measurable space, and joint count independence are explicit additions.')
item(354,'P000585','remark','Finite interaction range gives conditional locality',r"""\ru{Взаимод. конечно}: \ru{независимость}; the sketch separates an inner region from the exterior by a collar of width one.""",r"""For a finite-range Gibbs specification, the conditional law inside \(O\), given its entire exterior configuration, depends only on exterior particles within the interaction range of \(O\). Consequently the interior and the farther exterior are conditionally independent given the collar. Unconditional independence does not follow.""",r"""The precise conditional-distribution framework was already established by \citet[Section 1]{dobrushin1968conditional}. The next talk supplies the missing conditional-law formula explicitly (1974-355.3--4).""",[D],match='partial')
item(354,'P000585','definition','Finite-range many-particle interaction potentials',r"""\(U(x_1,\ldots,x_j)=0\) if the diameter is at least one. A proposed infinite hard-core value is crossed out.""",r"""A symmetric family \(U_j\) is of range one if every \(U_j(x_1,\ldots,x_j)\) vanishes when the set of its arguments has diameter at least one. For a finite configuration, its energy sums \(U_j\) over unordered \(j\)-element subsets. Finite range and finite interaction order are separate conditions.""",r"""Finite-range interactions are standard in the conditional specification approach of \citet[Section 1]{dobrushin1968conditional}. The deleted line cannot be used as an assumption; the more explicit pair-potential model appears on P000587.""",[D],match='partial')
item(354,'P000585','claim','The unexplained termination of the potential sequence',r"""\ru{Посл. обрыв., т.к. становится \(\equiv+\infty\)} follows the partially cancelled hard-core clause.""",r"""The fragment does not identify which sequence terminates, or whether it means a maximum admissible particle number, a finite list of potentials, or an energy tending to infinity. A hard core bounds the number of particles in a bounded region, but finite interaction range alone does not bound interaction order.""",r"""Neither the crossed-out condition nor the following density resolves the intended assertion. Searches in the Dobrushin/Ruelle specification literature did not identify an exact theorem corresponding to this phrase.""",[],cls='F',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',status='As of November 2026: not identifiable; no open problem is extracted from the cancelled shorthand.')
item(354,'P000585-P000586','construction','Finite-volume Gibbs density and particle-number sectors',r"""The notes write \(d(X)=e^{-\sum U_j}\), call it \(d(\mathrm{Gibbs})/d\mu\), and then use \(m^{\otimes n}\) on \(K^n\).""",r"""For a fixed exterior condition \(Y\), define \(dG_K^Y=Z_K(Y)^{-1}e^{-H_K(X\mid Y)}d\Pi_{m,K}(X)\), assuming \(0<Z_K(Y)<\infty\). Conditional on a specified particle number \(n\), one may instead normalize \(e^{-H_K}\) against the symmetric pushforward of \(m^{\otimes n}\). The grand-canonical version includes all \(n\), with \(1/n!\) factors.""",r"""\citet[Section 5]{ruelle1970superstable} treats the normalized finite-volume measures and their limits. The notebook omits normalization and passes between labelled coordinates and unordered configurations without specifying the ensemble; P000587 restores the partition function.""",[R],reconstruction='The two ensemble interpretations are separated rather than choosing one silently.')
corr('P000585','Configuration count cylinder',r"""\(\{K:|X\cap K|=n\}\)""",r"""\(\{X:|X\cap K|=n\}\), with \(K\) fixed.""",'The scan visibly binds K. The surrounding prose defines a measure on configurations X.')
corr('P000585','Finite-range independence slogan','Finite interaction: independence.','Conditional independence of the interior and distant exterior given the intervening collar.','The collar diagram and the next dated session identify the conditional Gibbs interpretation.')
corr('P000585-P000586','Gibbs Radon--Nikodym density',r"""\(dG/d\mu=e^{-H}\)""",r"""\(dG/d\mu=Z^{-1}e^{-H}\), when \(0<Z<\infty\).""",'No partition factor is present in the scan; P000587 supplies it.')
save()

talk(355,'1975-02-24','Ya. G. Sinai','P000585-P000591','Gibbs specifications, uniqueness, and low-temperature phase diagrams',r"""The notes begin on P000587 (the overwritten day is tentatively read 24) and end on P000589. Continuum Gibbs kernels lead to existence and uniqueness, then to finite-spin lattice systems and the low-temperature theorem soon published by Pirogov and Sinai. The first part is older Dobrushin--Ruelle theory; the phase-diagram part is a prepublication occurrence, preceding the papers received on 21 April 1975. Gelfand asks about a \(p\)-adic analogue without specifying the underlying model.""")
item(355,'P000587','definition','Poisson configurations on an infinite measured metric space',r"""The Poisson count formula is repeated on \(\mathbb R^2\), then on \((M,m)\); \(m(M)=\infty\) is the interesting case, with unspecified homogeneity.""",r"""Under the standard local-finiteness and diffuseness assumptions of 1974-354.2, infinite total intensity is compatible with a locally finite process. The count in each relatively compact \(O\) has mean \(m(O)\); disjoint counts are independent. Homogeneity is an extra symmetry assumption and is unnecessary for the definition.""",r"""This repeats the standard reference process in \citet[Section 5]{ruelle1970superstable}; it does not assert a new existence theorem for arbitrary measurable metric spaces.""",[R],match='partial')
item(355,'P000587','definition','Hard-core finite-range pair energy',r"""\(U_1\) is bounded, \(U_2\) symmetric, infinite at distances \(<\varepsilon\) and zero at distances \(\ge r_0\). The intermediate range is unspecified.""",r"""For a finite inside configuration \(X\) and exterior \(Y\), use \(H_O(X\mid Y)=\sum_{x\in X}U_1(x)+\sum_{\{x,x'\}\subset X}U_2(x,x')+\sum_{x\in X,y\in Y}U_2(x,y)\). Each inside pair is counted once. A lower bound and appropriate regularity on the annulus \(\varepsilon\le d(x,y)<r_0\) are needed for subsequent existence claims.""",r"""\citet[Sections 1 and 5]{ruelle1970superstable} gives stability and regularity conditions for such continuum energies. Hard core and finite range alone are not a complete theorem hypothesis on an arbitrary metric measure space.""",[R],match='partial')
item(355,'P000587','definition','The DLR conditional probability equation',r"""The conditional density in \(O\) is the exponential of the one-body, inside-pair and inside--outside energies, divided by \(\Xi(Y;O)\).""",r"""A probability \(\mu\) is Gibbs for a specified energy if, for every bounded region \(O\), its regular conditional law given the outside configuration equals \(\gamma_O(dX\mid Y)=\Xi(Y;O)^{-1}e^{-H_O(X\mid Y)}\Pi_{m,O}(dX)\), for \(\mu\)-almost every \(Y\). Here \(\Xi\) is the integral of the numerator, finite and positive on admissible boundary conditions.""",r"""This is the continuum conditional Gibbs formalism already treated in \citet[Section 5]{ruelle1970superstable}; compare the finite-state formulation of \citet[Section 1]{dobrushin1968conditional}. Earlier seminar context: 1970-195.4 and 1970-200.4.""",[R,D],literal='correct')
item(355,'P000587','theorem','The boundary collar is sufficient exterior information',r"""Everything depends only on the points of \(Y\) in the \(r_0\)-neighbourhood of \(O\).""",r"""For the finite-range pair energy just defined, \(\gamma_O(\,\cdot\mid Y)\) depends only on \(Y\cap\{y\notin O:d(y,O)<r_0\}\). This is the spatial Markov property of the specification, not independence of the unconditioned field.""",r"""The assertion follows directly from the displayed energy and is part of the established specification formalism in \citet[Section 1]{dobrushin1968conditional}. It resolves the shorthand in 1974-354.3.""",[D],literal='correct',match='partial')
item(355,'P000587','remark','Gelfand interprets conditioning as disintegration',r"""Gelfand invokes a measurable partition and a general Fubini theorem; the measure on exterior configurations is induced by inverse images.""",r"""On standard Borel configuration spaces, the restriction map \(r:X\mapsto X\cap O^c\) has a pushforward probability \(r_*\mu\) and a conditional probability kernel \(\mu_Y\), unique \(r_*\mu\)-almost everywhere, satisfying \(\int F\,d\mu=\int(\int F\,d\mu_Y)\,d(r_*\mu)(Y)\). The kernel is supported on the corresponding fibres almost everywhere.""",r"""This is the classical measurable-partition/disintegration result of \citet{rokhlin1949measure}, published in Russian in 1949 (English translation 1952). Record 358 returns to its precise kernel definition. The notebook does not state hypotheses sufficient for completely arbitrary measurable spaces.""",[RO],speaker='I. M. Gelfand',verification='publisher metadata checked',match='partial')
item(355,'P000587-P000588','theorem','Consistency for nested regions',r"""A diagram with \(O_2\subset O_1\) accompanies integration over all ways to fill in the smaller missing configuration.""",r"""For a Gibbs specification and bounded \(O_2\subset O_1\), \(\gamma_{O_1}\gamma_{O_2}=\gamma_{O_1}\), where kernels act successively on bounded measurable observables. This expresses the tower property and is the compatibility condition required before seeking a global measure.""",r"""\citet[Section 1]{dobrushin1968conditional} formulates compatible conditional distributions before its existence theorem. The diagram is interpreted using the normalized kernel on the preceding page.""",[D],reconstruction='The kernel identity is a precise reconstruction of the nested-region explanation.',match='partial')
item(355,'P000588','theorem','Existence from finite-volume limits',r"""A Gibbs measure exists; exhaust \(M\) by compact \(O_k\), construct measures there and choose a convergent subsequence. The notes call each local configuration space compact.""",r"""A verified sufficient continuum theorem is this: for a translation-invariant superstable, lower-regular pair potential with \(\int_{\mathbb R^d}|1-e^{-\beta U(x)}|\,dx<\infty\), the finite-volume free-boundary measures have subsequential local limits giving tempered Gibbs states. In the hard-core model, local particle numbers are bounded on compact closures, but passage through boundaries and discontinuous potentials still needs justification.""",r"""\citet[Theorem 5.5]{ruelle1970superstable} proves the stated version in 1970. The unrestricted configuration space is not compact: arbitrarily many particles or colliding particles obstruct the naive argument. Thus the notebook sketch is not a proof at its stated generality.""",[R],reconstruction='Ruelle’s explicit hypotheses replace the unspecified general metric-space claim.',literal='false as written',match='partial',status='As of November 2026: established under standard stability and regularity assumptions; the notebook’s arbitrary-space compactness argument remains insufficient, not an open existence problem.')
item(355,'P000588','theorem','One-dimensional uniqueness',r"""For \(M=\mathbb R\) with Lebesgue measure, the Gibbs measure is said to be unique.""",r"""The intended assertion is uniqueness for the usual one-dimensional finite-range gas at finite positive temperature and activity, with a hard core and bounded finite interaction away from the core. It is not a uniqueness theorem for every measurable pair potential satisfying only the two displayed endpoint values, nor for arbitrary infinite-range interactions.""",r"""One-dimensional uniqueness belongs to the earlier Dobrushin--Ruelle theory. \citet[Section 2]{dobrushin1968conditional} contains the finite-state one-dimensional result; the continuum version in precisely the notebook’s scope was not recovered in the checked sources. Compare the older seminar occurrence 1970-195.5.""",[D],match='partial',verification='indirect',confidence='medium',status='As of November 2026: standard one-dimensional finite-range uniqueness is established; the literal missing regularity and interaction assumptions prevent an exact source match here.')
item(355,'P000588','theorem','Uniqueness at sufficiently low activity',r"""For \(U_1=0\) and \(m\le c\) times Lebesgue measure, sufficiently small \(c\) gives uniqueness.""",r"""For the translation-invariant superstable, lower-regular continuum pair potentials of 1974-355.7, the tempered Gibbs state is unique at sufficiently small positive activity \(z\). The smallness threshold depends on temperature and the potential. An inhomogeneous intensity dominated by \(c\,dx\) requires a corresponding uniform contraction estimate.""",r"""\citet[Theorem 5.7]{ruelle1970superstable} is an exact low-activity theorem for the homogeneous subclass. The notebook’s more general dominated measure is not separately verified here.""",[R],match='partial',confidence='medium')
item(355,'P000588','construction','Lattice gas with a Bernoulli reference measure',r"""Replace \(\mathbb R^d\) by \(\mathbb Z^d\), \(d\ge2\), and use the symmetric Bernoulli measure on occupation variables.""",r"""A simple lattice gas is a spin field \(\eta\in\{0,1\}^{\mathbb Z^d}\). On a finite region \(\Lambda\), use the product Bernoulli-\(1/2\) reference and density proportional to \(e^{-\beta H_\Lambda(\eta\mid\xi)}\). A one-site field can absorb a different positive Bernoulli parameter. Finite-range energies define consistent finite-volume kernels.""",r"""This is a special case of \citet[Section 1]{dobrushin1968conditional}, published 1968, and the lattice setting of \citet[Section 1]{pirogovsinai1975phase}. The move to \(d\ge2\) prepares phase coexistence.""",[D,PS],literal='correct')
item(355,'P000588','theorem','Weak-interaction or high-temperature uniqueness',r"""For sufficiently small \(U_1,U_2\), the Gibbs measure is unique.""",r"""For a finite-alphabet specification on \(\mathbb Z^d\), let \(c_{ij}\) be the supremum total-variation change in the conditional distribution at site \(i\) when only the exterior spin at \(j\) is changed. If \(\sup_i\sum_jc_{ij}<1\), there is at most one Gibbs measure; compactness and quasilocality supply existence. Bounded finite-range interactions satisfy this criterion at sufficiently high temperature.""",r"""\citet[Theorem 2]{dobrushin1968conditional} gives the contraction criterion; \citet{dobrushin1968uniqueness} develops uniqueness and phase transitions. Smallness of the one-site field alone is not essential: the dependence on other sites is what is controlled.""",[D,DU],reconstruction='The dimensionless contraction condition replaces an unspecified norm-smallness assertion.',match='partial')
item(355,'P000588-P000589','definition','Periodic ground configurations and local energy differences',r"""Translation-invariant \(U_1=\alpha\), even \(U_2(x-y)\), periodic configurations, and minimization against finite changes define the ground states.""",r"""For a finite-range translation-invariant lattice Hamiltonian, a configuration \(g\) is a ground state if every finite modification \(\eta\) satisfies \(H(\eta)-H(g)\ge0\), where only terms meeting the modified region enter the finite difference. Periodicity is an additional property, not part of the general ground-state definition.""",r"""The local-energy definition and periodic reference states are the framework of \citet[Section 1]{pirogovsinai1975phase}. The 1975 talk predates that paper but uses an older standard notion of ground configuration.""",[PS],match='partial')
item(355,'P000589','claim','A finite set of periodic reference ground states',r"""\(G(U)\) is taken to be finite, with \(|G(U)|=k\).""",r"""The phase-diagram theorem assumes that the model has exactly a specified finite family \(g_1,\ldots,g_k\) of periodic ground configurations, modulo the stated periodicity convention. Finite-range translation invariance does not imply this hypothesis; highly degenerate models can have infinitely many ground configurations.""",r"""This is a hypothesis of \citet[Section 1 and Theorem 1]{pirogovsinai1975phase}, not a universal theorem. The exact low-temperature conclusion depends also on Peierls stability and independent perturbations.""",[PS],literal='correct with missing hypotheses')
item(355,'P000589','definition','Peierls energy cost for defects',r"""A site lies on the boundary if its neighbourhood agrees with no ground state; \(H(X')-H(X)\ge g\,\Gamma(X')\).""",r"""Choose a fixed coarse-graining scale large enough to recognize the periodic ground patterns and the interaction range. A bad cube is one not locally matching any reference pattern. The Peierls condition requires the energy excess of a finite perturbation of a ground state to be at least \(\tau>0\) times the number of bad cubes, with \(\tau\) uniform.""",r"""\citet[Definitions 1.2--1.3]{pirogovsinai1975phase} gives the matching definition. This particular contour stability hypothesis is part of the Pirogov--Sinai theorem announced here and published later in 1975.""",[PS],cls='A',reconstruction='The unspecified neighbourhood and boundary cardinality are replaced by the finite-scale definition in the paper.')
item(355,'P000589','construction','Independent parameters unfold the ground-state energies',r"""\(U_\mu=U+\sum_{j=1}^{k-1}\mu_jU^{(j)}\), near \(\mu=0\), and a condition written \(G(U_\mu)\le G(U)\).""",r"""Choose \(k-1\) perturbing interactions whose energy-density differences on \(g_1,\ldots,g_k\), relative to one reference state, form a nonsingular \((k-1)\times(k-1)\) matrix. The ensuing theorem is local in this parameter neighbourhood, with the listed periodic ground states as its reference phases. A set of ground states is not numerically ordered.""",r"""\citet[Definition 1.4 and Theorem 1]{pirogovsinai1975phase} supplies the independence condition. The notebook’s inequality is plausibly shorthand for inclusion/no new reference states, but its intended meaning is not certain.""",[PS],cls='A',reconstruction='The nonsingularity condition is recovered from the matched theorem; the ambiguous set inequality is not silently converted into a cardinality bound.',match='partial',confidence='medium')
item(355,'P000589','theorem','Low-temperature coexistence and phase-diagram strata',r"""For large \(\beta\), a point \(\mu(\beta)\) has \(k\) Gibbs distributions, \(k\) emanating curves have \(k-1\), and \(\binom{k}{2}\) surfaces have \(k-2\).""",r"""Under the finite-state, finite-range, finitely many periodic ground states, Peierls, and independent-perturbation hypotheses, the low-temperature phase diagram near the reference point has a coexistence locus where \(k\) stable periodic pure phases coexist. Its adjacent local strata correspond to subsets of the stable phases, with the expected codimensions. Counts refer to stable pure phases, not all Gibbs probability measures; convex mixtures already give infinitely many measures when two phases coexist.""",r"""This is the central match to \citet[Theorem 1]{pirogovsinai1975phase}, with proof continued in \citet{pirogovsinai1976phase}. Both papers were received on 21 April 1975, after this 24 February notebook occurrence, and appeared in 1975 and 1976 respectively. The notebook’s unqualified uniqueness and total-measure count are stronger than the safely matched statement.""",[PS,PS2],cls='A',literal='false as written',match='partial',status='As of November 2026: the Pirogov--Sinai local phase-diagram theory is established. This entry is evidence of an early seminar presentation, not a still-open conjecture; no completeness claim about all nonperiodic or interface Gibbs states is inferred.')
item(355,'P000589','question','Gelfand asks for a p-adic Gibbs analogue',r"""\ru{Вопрос Г. Гиббсовские распределения в \(p\)-адическом случае}.""",r"""The note asks for a \(p\)-adic analogue but does not say whether the sites, spin space, interaction values, or probability values are \(p\)-adic, or whether existence, uniqueness, phase transitions, or a particular construction is sought. These interpretations lead to different mathematical problems.""",r"""The Dobrushin--Ruelle specification framework \citep{dobrushin1968conditional,ruelle1970superstable} suggests one possible real-probability model over a non-Archimedean site space, but that editorial model is not an identified intended statement. Search results for later \(p\)-adic Gibbs measures are therefore only thematic and are not claimed as a solution of this question.""",[D,R],speaker='I. M. Gelfand',cls='F',literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',status='As of November 2026: no definite historical problem is recoverable; the broad prompt is not classified as an undeveloped research gap.')
corr('P000588','Compactness in the Gibbs existence sketch','The space of configurations in a bounded region is compact.','A compactness or tightness argument must use the hard-core bound and a specified topology; unrestricted locally finite configurations in a bounded region are not compact.','The scan states compactness without qualifying the configuration class; the next limiting step also needs boundary regularity.')
corr('P000589','Number of Gibbs distributions at coexistence',r"""\(k\) Gibbs distributions, with \(k-1\) and \(k-2\) along adjacent strata.""",r"""\(k\), \(k-1\), and \(k-2\) stable pure periodic phases in the local phase diagram.""",r"""The scan says distributions. Convexity produces infinitely many Gibbs measures from any two distinct ones; \citet[Theorem 1]{pirogovsinai1975phase} is a pure-phase theorem.""")
corr('P000589','Ground-state perturbation comparison',r"""\(G(U_\mu)\le G(U)\)""",r"""Possibly \(G(U_\mu)\subseteq G(U)\), or a cardinality comparison; retain uncertainty.""",'The scan contains a relation resembling an inequality between set-valued symbols. Its intended interpretation is not recoverable with certainty.',type='ambiguity')
save()
